describe('Active Sessions Management', () => {
  beforeEach(() => {
    cy.visit('/profile/sessions');
    cy.login('testuser@example.com', 'password123');
  });

  it('should display all active sessions with device information', () => {
    cy.get('[data-testid="sessions-list"]').should('be.visible');
    cy.get('[data-testid="session-item"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="session-item"]').first().within(() => {
      cy.get('[data-testid="device-name"]').should('be.visible');
      cy.get('[data-testid="device-type"]').should('be.visible');
      cy.get('[data-testid="last-active"]').should('be.visible');
      cy.get('[data-testid="ip-address"]').should('be.visible');
      cy.get('[data-testid="logout-btn"]').should('be.visible');
    });
  });

  it('should logout from a specific session when logout button is clicked', () => {
    cy.get('[data-testid="session-item"]').eq(1).within(() => {
      cy.get('[data-testid="logout-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-logout-btn"]').click();

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Session logged out successfully');

    cy.get('[data-testid="session-item"]').should('have.length.lessThan', 2);
  });

  it('should handle logout cancellation gracefully', () => {
    cy.get('[data-testid="session-item"]').first().within(() => {
      cy.get('[data-testid="logout-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="cancel-logout-btn"]').click();

    cy.get('[data-testid="confirmation-modal"]').should('not.exist');
    cy.get('[data-testid="session-item"]').should('have.length.greaterThan', 0);
  });

  it('should display current session with a badge indicator', () => {
    cy.get('[data-testid="session-item"]').each(($session) => {
      cy.wrap($session).within(() => {
        cy.get('[data-testid="current-session-badge"]').then(($badge) => {
          if ($badge.length > 0) {
            cy.wrap($badge).should('contain', 'Current Session');
            cy.get('[data-testid="logout-btn"]').should('be.disabled');
          }
        });
      });
    });
  });

  it('should handle empty sessions list when no active sessions exist', () => {
    cy.intercept('GET', '/api/sessions', { body: { sessions: [] } });
    cy.reload();

    cy.get('[data-testid="sessions-list"]').should('be.visible');
    cy.get('[data-testid="session-item"]').should('not.exist');
    cy.get('[data-testid="empty-state-message"]')
      .should('be.visible')
      .and('contain', 'No active sessions');
  });

  it('should refresh sessions list and show updated data', () => {
    cy.get('[data-testid="refresh-btn"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="sessions-list"]').should('be.visible');
  });
});
